import { useEffect, useMemo, useReducer } from 'react'
import './App.css'
import {
  APPROACHES,
  ALL_RED_MS,
  LANE_KINDS,
  LANE_LABELS,
  LEFT_MIN_MS,
  TIMINGS,
  VIEW,
  YELLOW_MS,
  INITIAL_STATE,
  LANE_ORDER,
  buildPathForCar,
  carAngleAtProgress,
  carPositionAtProgress,
  getLaneKey,
  getLaneSignal,
  getPhaseLabel,
  getPhaseRemainingMs,
  getTrafficSummary,
  reducer,
  type AppAction,
  type Crossing,
  type SimState,
} from './sim'

function App() {
  const [state, dispatch] = useReducer(reducer, INITIAL_STATE)

  useEffect(() => {
    const intervalId = window.setInterval(() => {
      dispatch({ type: 'tick', deltaMs: TIMINGS.tickMs })
    }, TIMINGS.tickMs)

    return () => window.clearInterval(intervalId)
  }, [])

  useEffect(() => {
    document.title = `${getPhaseLabel(state)} | Traffic Intersection`
  }, [state])

  const summary = useMemo(() => getTrafficSummary(state.cars), [state.cars])
  const remainingMs = getPhaseRemainingMs(state)
  const phaseLabel = getPhaseLabel(state)

  return (
    <div className="app-shell">
      <header className="topbar">
        <div>
          <p className="eyebrow">Option 4 hybrid UI</p>
          <h1>Traffic Intersection Simulator</h1>
          <p className="lede">
            Timer-driven light phases, pedestrian walk requests, and moving cars
            across a four-way intersection.
          </p>
        </div>

        <div className="topbar-stats">
          <StatCard label="Phase" value={phaseLabel} />
          <StatCard
            label="Countdown"
            value={remainingMs === Number.POSITIVE_INFINITY ? 'hold' : `${Math.ceil(remainingMs / 1000)}s`}
          />
          <StatCard label="Priority" value={state.priorityAxis} />
        </div>
      </header>

      <main className="layout">
        <section className="visual-card">
          <div className="visual-header">
            <div>
              <h2>Intersection view</h2>
              <p>
                Green shows straight-through traffic, yellow is the transition,
                and protected left turns come after the red-clearance gap.
              </p>
            </div>
            <div className="legend">
              <LegendDot color="green" label="Straight" />
              <LegendDot color="yellow" label="Yellow" />
              <LegendDot color="orange" label="Permissive left" />
              <LegendDot color="red" label="Stop" />
            </div>
          </div>

          <div className="stage-wrap">
            <svg
              className="stage"
              viewBox={`0 0 ${VIEW.width} ${VIEW.height}`}
              role="img"
              aria-label="Traffic intersection simulator"
            >
              <defs>
                <linearGradient id="road-fill" x1="0" x2="0" y1="0" y2="1">
                  <stop offset="0%" stopColor="#25303b" />
                  <stop offset="100%" stopColor="#182029" />
                </linearGradient>
                <linearGradient id="glow" x1="0" x2="1" y1="0" y2="1">
                  <stop offset="0%" stopColor="#ffffff" stopOpacity="0.22" />
                  <stop offset="100%" stopColor="#ffffff" stopOpacity="0" />
                </linearGradient>
              </defs>

              <rect width={VIEW.width} height={VIEW.height} fill="url(#glow)" opacity="0.25" />

              <rect
                x={VIEW.centerX - VIEW.roadBand / 2}
                y={0}
                width={VIEW.roadBand}
                height={VIEW.height}
                fill="url(#road-fill)"
                rx="18"
              />
              <rect
                x={0}
                y={VIEW.centerY - VIEW.roadBand / 2}
                width={VIEW.width}
                height={VIEW.roadBand}
                fill="url(#road-fill)"
                rx="18"
              />

              <rect
                x={VIEW.centerX - VIEW.intersectionHalf}
                y={VIEW.centerY - VIEW.intersectionHalf}
                width={VIEW.intersectionHalf * 2}
                height={VIEW.intersectionHalf * 2}
                fill="#10151b"
                opacity="0.9"
                rx="18"
              />

              <g className="lane-markings" stroke="#d9e5ea" strokeOpacity="0.75">
                {['N', 'S'].map((approach) =>
                  LANE_ORDER.map((lane, laneIndex) => {
                    const laneX = laneCenterX(state, approach as 'N' | 'S', laneIndex)
                    return (
                      <g key={`${approach}-${lane}`}>
                        <line
                          x1={laneX}
                          x2={laneX}
                          y1={approach === 'N' ? 0 : VIEW.centerY + VIEW.intersectionHalf}
                          y2={approach === 'N' ? VIEW.centerY - VIEW.intersectionHalf : VIEW.height}
                          strokeDasharray="18 16"
                          strokeWidth="2"
                        />
                        <text x={laneX} y={approach === 'N' ? 40 : VIEW.height - 20} className="lane-tag">
                          {LANE_LABELS[lane]}
                        </text>
                      </g>
                    )
                  }),
                )}
                {['W', 'E'].map((approach) =>
                  LANE_ORDER.map((lane, laneIndex) => {
                    const laneY = laneCenterY(state, approach as 'W' | 'E', laneIndex)
                    return (
                      <g key={`${approach}-${lane}`}>
                        <line
                          y1={laneY}
                          y2={laneY}
                          x1={approach === 'W' ? 0 : VIEW.centerX + VIEW.intersectionHalf}
                          x2={approach === 'W' ? VIEW.centerX - VIEW.intersectionHalf : VIEW.width}
                          strokeDasharray="18 16"
                          strokeWidth="2"
                        />
                        <text x={approach === 'W' ? 34 : VIEW.width - 34} y={laneY - 10} className="lane-tag">
                          {LANE_LABELS[lane]}
                        </text>
                      </g>
                    )
                  }),
                )}
              </g>

              {APPROACHES.map((approach) => {
                const signal = getLaneSignal(state, approach)
                return (
                  <g key={approach} className="signal-cluster">
                    <SignalCluster approach={approach} signal={signal} />
                  </g>
                )
              })}

              <g className="crosswalks" opacity="0.65">
                <rect x={VIEW.centerX - VIEW.intersectionHalf - 28} y={VIEW.centerY - 96} width={18} height={192} fill="#f5f0d8" />
                <rect x={VIEW.centerX + VIEW.intersectionHalf + 10} y={VIEW.centerY - 96} width={18} height={192} fill="#f5f0d8" />
                <rect x={VIEW.centerX - 96} y={VIEW.centerY - VIEW.intersectionHalf - 28} width={192} height={18} fill="#f5f0d8" />
                <rect x={VIEW.centerX - 96} y={VIEW.centerY + VIEW.intersectionHalf + 10} width={192} height={18} fill="#f5f0d8" />
              </g>

              <g className="cars">
                {state.cars
                  .slice()
                  .sort((left, right) => left.progress - right.progress)
                  .map((car) => {
                    const { x, y } = carPositionAtProgress(car)
                    const rotation = carAngleAtProgress(car)
                    return (
                      <g key={car.id} transform={`translate(${x} ${y}) rotate(${rotation})`}>
                        <rect
                          x={-car.length / 2}
                          y={-car.width / 2}
                          width={car.length}
                          height={car.width}
                          rx="4"
                          className={`car car-${car.intent}`}
                        />
                        <circle cx="0" cy="0" r="1.8" className="car-dot" />
                      </g>
                    )
                  })}
              </g>

              <g className="center-labels">
                <text x={VIEW.centerX} y={VIEW.centerY - 12} textAnchor="middle" className="center-title">
                  intersection core
                </text>
                <text x={VIEW.centerX} y={VIEW.centerY + 14} textAnchor="middle" className="center-subtitle">
                  protected lefts + walk requests
                </text>
              </g>
            </svg>
          </div>
        </section>

        <aside className="sidebar">
          <PanelSection title="Controls">
            <div className="button-row">
              <button type="button" onClick={() => dispatch({ type: 'walk', crossing: 'NS' })}>
                Walk NS crossing
              </button>
              <button type="button" onClick={() => dispatch({ type: 'walk', crossing: 'EW' })}>
                Walk EW crossing
              </button>
            </div>
            <div className="button-row">
              <button type="button" onClick={() => dispatch({ type: 'togglePause' })}>
                {state.paused ? 'Resume' : 'Pause'}
              </button>
              <button type="button" onClick={() => dispatch({ type: 'reset' })}>
                Reset
              </button>
            </div>
            <div className="speed-row">
              {[0.5, 1, 1.5, 2].map((speed) => (
                <button
                  key={speed}
                  type="button"
                  className={state.speed === speed ? 'selected' : ''}
                  onClick={() => dispatch({ type: 'speed', speed })}
                >
                  {speed}x
                </button>
              ))}
            </div>
          </PanelSection>

          <PanelSection title="Signal state">
            <dl className="signal-grid">
              <InfoRow label="Active axis" value={state.activeAxis} />
              <InfoRow label="Priority axis" value={state.priorityAxis} />
              <InfoRow label="Phase age" value={`${Math.floor((state.now - state.phaseStartedAt) / 1000)}s`} />
              <InfoRow label="Minimum straight" value={`${TIMINGS.straightMinMs / 1000}s`} />
              <InfoRow label="Minimum left" value={`${LEFT_MIN_MS / 1000}s`} />
              <InfoRow label="Yellow" value={`${YELLOW_MS / 1000}s`} />
              <InfoRow label="All-red" value={`${ALL_RED_MS / 1000}s`} />
            </dl>
          </PanelSection>

          <PanelSection title="Pedestrians">
            {(['NS', 'EW'] as Crossing[]).map((crossing) => {
              const walk = state.walks[crossing]
              return (
                <div key={crossing} className="walk-card">
                  <div>
                    <strong>Cross {crossing}</strong>
                    <p>
                      {walk.active
                        ? `Walking until ${Math.ceil(((walk.activeUntil ?? state.now) - state.now) / 1000)}s`
                        : walk.requested
                          ? 'Queued'
                          : 'Idle'}
                    </p>
                  </div>
                  <button type="button" onClick={() => dispatch({ type: 'walk', crossing })}>
                    Request
                  </button>
                </div>
              )
            })}
          </PanelSection>

          <PanelSection title="Traffic summary">
            <div className="summary-grid">
              <SummaryChip label="Cars" value={summary.totalCars} />
              <SummaryChip label="NS demand" value={summary.axisDemand.NS} />
              <SummaryChip label="EW demand" value={summary.axisDemand.EW} />
              <SummaryChip label="Left NS" value={summary.leftDemand.NS} />
              <SummaryChip label="Left EW" value={summary.leftDemand.EW} />
              <SummaryChip label="Walks active" value={summary.walksActive} />
            </div>

            {(['N', 'S', 'E', 'W'] as const).map((approach) => (
              <div key={approach} className="approach-card">
                <div className="approach-title">{approach} approach</div>
                <div className="lane-counts">
                  {LANE_ORDER.map((lane) => {
                    const laneKey = getLaneKey(approach, lane)
                    return (
                      <span key={laneKey}>
                        {LANE_LABELS[lane]}: {summary.byLane[laneKey] ?? 0}
                      </span>
                    )
                  })}
                </div>
              </div>
            ))}
          </PanelSection>
        </aside>
      </main>
    </div>
  )
}

function StatCard({ label, value }: { label: string; value: string }) {
  return (
    <div className="stat-card">
      <span>{label}</span>
      <strong>{value}</strong>
    </div>
  )
}

function LegendDot({ color, label }: { color: string; label: string }) {
  return (
    <div className="legend-item">
      <span className={`legend-dot ${color}`} />
      <span>{label}</span>
    </div>
  )
}

function PanelSection({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <section className="panel-section">
      <h3>{title}</h3>
      {children}
    </section>
  )
}

function InfoRow({ label, value }: { label: string; value: string }) {
  return (
    <>
      <dt>{label}</dt>
      <dd>{value}</dd>
    </>
  )
}

function SummaryChip({ label, value }: { label: string; value: number }) {
  return (
    <div className="summary-chip">
      <span>{label}</span>
      <strong>{value}</strong>
    </div>
  )
}

function SignalCluster({
  approach,
  signal,
}: {
  approach: 'N' | 'S' | 'E' | 'W'
  signal: ReturnType<typeof getLaneSignal>
}) {
  const layout = signalLayout(approach)

  return (
    <g transform={`translate(${layout.x} ${layout.y})`}>
      <rect x={-36} y={-16} width={72} height={32} rx={14} className="signal-housing" />
      {layout.lights.map((light, index) => {
        const color = index === 0 ? signal.left : index === 1 ? signal.straight : signal.right
        return <circle key={light.key} cx={light.cx} cy={light.cy} r={6.5} className={`signal-light ${color}`} />
      })}
    </g>
  )
}

function laneCenterX(state: SimState, approach: 'N' | 'S', laneIndex: number) {
  return approach === 'N'
    ? VIEW.centerX - VIEW.roadBand / 2 + 28 + laneIndex * 32
    : VIEW.centerX + 28 + laneIndex * 32
}

function laneCenterY(state: SimState, approach: 'W' | 'E', laneIndex: number) {
  return approach === 'W'
    ? VIEW.centerY - VIEW.roadBand / 2 + 28 + laneIndex * 32
    : VIEW.centerY + 28 + laneIndex * 32
}

function signalLayout(approach: 'N' | 'S' | 'E' | 'W') {
  if (approach === 'N') {
    return { x: VIEW.centerX - 96, y: VIEW.centerY - VIEW.intersectionHalf - 40, lights: signalLights() }
  }

  if (approach === 'S') {
    return { x: VIEW.centerX + 96, y: VIEW.centerY + VIEW.intersectionHalf + 40, lights: signalLights() }
  }

  if (approach === 'W') {
    return { x: VIEW.centerX - VIEW.intersectionHalf - 40, y: VIEW.centerY + 96, lights: signalLights() }
  }

  return { x: VIEW.centerX + VIEW.intersectionHalf + 40, y: VIEW.centerY - 96, lights: signalLights() }
}

function signalLights() {
  return [
    { key: 'left', cx: -22, cy: 0 },
    { key: 'straight', cx: 0, cy: 0 },
    { key: 'right', cx: 22, cy: 0 },
  ]
}

export default App

export const TIMINGS = {
  tickMs: 100,
  straightMinMs: 20_000,
  leftMinMs: 10_000,
  yellowMs: 3_000,
  allRedMs: 1_000,
  walkMs: 10_000,
} as const

export const ALL_RED_MS = TIMINGS.allRedMs
export const LEFT_MIN_MS = TIMINGS.leftMinMs
export const YELLOW_MS = TIMINGS.yellowMs

export const VIEW = {
  width: 1_200,
  height: 840,
  centerX: 600,
  centerY: 420,
  roadBand: 312,
  intersectionHalf: 92,
} as const

export const APPROACHES = ['N', 'S', 'E', 'W'] as const
export const AXES = ['NS', 'EW'] as const
export const LANE_ORDER = ['left', 'straightA', 'straightB', 'right'] as const

export const LANE_LABELS = {
  left: 'L',
  straightA: 'S1',
  straightB: 'S2',
  right: 'R',
} as const

export type Approach = (typeof APPROACHES)[number]
export type Axis = (typeof AXES)[number]
export type LaneKind = (typeof LANE_ORDER)[number]
export type Intent = 'left' | 'straight' | 'right'
export type Phase = 'straightGreen' | 'straightYellow' | 'allRedToLeft' | 'leftGreen' | 'leftYellow' | 'allRedToSwap'
export type SignalColor = 'red' | 'yellow' | 'green' | 'flashingOrange'
export type Crossing = 'NS' | 'EW'
export type LaneKey = `${Approach}-${LaneKind}`

export interface Point {
  x: number
  y: number
}

export interface Car {
  id: number
  approach: Approach
  lane: LaneKind
  intent: Intent
  path: Point[]
  pathLength: number
  progress: number
  stopDistance: number
  speed: number
  length: number
  width: number
  color: string
}

export interface WalkState {
  requested: boolean
  active: boolean
  activeUntil: number | null
}

export interface SimState {
  now: number
  phase: Phase
  activeAxis: Axis
  phaseStartedAt: number
  priorityAxis: Axis
  paused: boolean
  speed: number
  cars: Car[]
  walks: Record<Crossing, WalkState>
  nextSpawnAt: Record<LaneKey, number>
  nextId: number
}

export interface TrafficSummary {
  totalCars: number
  axisDemand: Record<Axis, number>
  leftDemand: Record<Axis, number>
  walksActive: number
  byLane: Partial<Record<LaneKey, number>>
}

export type AppAction =
  | { type: 'tick'; deltaMs: number }
  | { type: 'walk'; crossing: Crossing }
  | { type: 'togglePause' }
  | { type: 'speed'; speed: number }
  | { type: 'reset' }

const LANE_COLORS: Record<Intent, string> = {
  left: '#f35d3f',
  straight: '#5fb1ff',
  right: '#b4c6d4',
}

const laneShape = {
  carLength: 18,
  carWidth: 10,
  turnInset: 30,
} as const

const laneSpacing = 32

const laneSpawnProfiles: Record<LaneKind, { minMs: number; maxMs: number; speed: number }> = {
  left: { minMs: 4_000, maxMs: 8_000, speed: 68 },
  straightA: { minMs: 1_800, maxMs: 4_200, speed: 88 },
  straightB: { minMs: 2_000, maxMs: 4_600, speed: 90 },
  right: { minMs: 3_200, maxMs: 6_800, speed: 96 },
}

export const INITIAL_STATE: SimState = createInitialState()

export function reducer(state: SimState, action: AppAction): SimState {
  switch (action.type) {
    case 'tick':
      return state.paused ? state : tick(state, action.deltaMs)
    case 'walk':
      return {
        ...state,
        walks: {
          ...state.walks,
          [action.crossing]: {
            ...state.walks[action.crossing],
            requested: true,
          },
        },
      }
    case 'togglePause':
      return { ...state, paused: !state.paused }
    case 'speed':
      return { ...state, speed: action.speed }
    case 'reset':
      return createInitialState()
    default:
      return state
  }
}

export function tick(state: SimState, deltaMs: number): SimState {
  const now = state.now + deltaMs * state.speed
  const walkedState = updateWalks(state, now)
  const summaryBefore = getTrafficSummary(state.cars)
  const advancedPhase = maybeAdvancePhase({ ...state, now, walks: walkedState }, summaryBefore)
  const summaryAfterPhase = getTrafficSummary(advancedPhase.cars)
  const movedCars = advanceCars(advancedPhase, deltaMs, summaryAfterPhase)
  const spawned = spawnCars({ ...advancedPhase, cars: movedCars }, now)

  return {
    ...advancedPhase,
    now,
    cars: spawned.cars,
    nextSpawnAt: spawned.nextSpawnAt,
    walks: walkedState,
  }
}

export function getPhaseLabel(state: SimState) {
  const prefix = state.activeAxis
  switch (state.phase) {
    case 'straightGreen':
      return `${prefix} straight green`
    case 'straightYellow':
      return `${prefix} straight yellow`
    case 'allRedToLeft':
      return `${prefix} all-red`
    case 'leftGreen':
      return `${prefix} left green`
    case 'leftYellow':
      return `${prefix} left yellow`
    case 'allRedToSwap':
      return `${prefix} all-red`
  }
}

export function getPhaseRemainingMs(state: SimState) {
  const elapsed = state.now - state.phaseStartedAt
  switch (state.phase) {
    case 'straightGreen': {
      const walkDeadline = Math.max(
        ...(['NS', 'EW'] as Crossing[]).map((crossing) => {
          const requiredAxis = crossing === 'NS' ? 'EW' : 'NS'
          const walk = state.walks[crossing]
          if (state.activeAxis !== requiredAxis || !walk.active || walk.activeUntil === null) {
            return 0
          }
          return walk.activeUntil - state.now
        }),
      )
      return Math.max(0, Math.max(TIMINGS.straightMinMs - elapsed, walkDeadline))
    }
    case 'straightYellow':
      return Math.max(0, TIMINGS.yellowMs - elapsed)
    case 'allRedToLeft':
    case 'allRedToSwap':
      return Math.max(0, TIMINGS.allRedMs - elapsed)
    case 'leftGreen':
      return Math.max(0, TIMINGS.leftMinMs - elapsed)
    case 'leftYellow':
      return Math.max(0, TIMINGS.yellowMs - elapsed)
  }
}

export function getTrafficSummary(cars: Car[]): TrafficSummary {
  const summary: TrafficSummary = {
    totalCars: cars.length,
    axisDemand: { NS: 0, EW: 0 },
    leftDemand: { NS: 0, EW: 0 },
    walksActive: 0,
    byLane: {},
  }

  for (const car of cars) {
    const axis = axisForApproach(car.approach)
    summary.axisDemand[axis] += 1
    if (car.intent === 'left') {
      summary.leftDemand[axis] += 1
    }
    const key = getLaneKey(car.approach, car.lane)
    summary.byLane[key] = (summary.byLane[key] ?? 0) + 1
  }

  return summary
}

export function getLaneSignal(state: SimState, approach: Approach): { left: SignalColor; straight: SignalColor; right: SignalColor } {
  const axis = axisForApproach(approach)
  const summary = getTrafficSummary(state.cars)
  const hasOpposingDemand = summary.axisDemand[oppositeAxis(axis)] > 0
  const hasLeftDemand = summary.leftDemand[axis] > 0

  if (state.activeAxis !== axis) {
    return { left: 'red', straight: 'red', right: 'red' }
  }

  switch (state.phase) {
    case 'straightGreen':
      return {
        left: hasOpposingDemand ? 'red' : hasLeftDemand ? 'flashingOrange' : 'red',
        straight: 'green',
        right: 'green',
      }
    case 'straightYellow':
      return { left: 'red', straight: 'yellow', right: 'yellow' }
    case 'allRedToLeft':
    case 'allRedToSwap':
      return { left: 'red', straight: 'red', right: 'red' }
    case 'leftGreen':
      return { left: 'green', straight: 'red', right: 'red' }
    case 'leftYellow':
      return { left: 'yellow', straight: 'red', right: 'red' }
  }
}

export function getLaneKey(approach: Approach, lane: LaneKind): LaneKey {
  return `${approach}-${lane}`
}

export function carPositionAtProgress(car: Car) {
  return pointAlongPath(car.path, car.progress)
}

export function carAngleAtProgress(car: Car) {
  return pointAlongPath(car.path, car.progress).angle
}

export function buildPathForCar(approach: Approach, lane: LaneKind, intent: Intent) {
  return buildCarPath(approach, lane, intent)
}

function tickPhase(state: SimState, summary: TrafficSummary): SimState {
  const elapsed = state.now - state.phaseStartedAt
  const currentWalk = activeWalkForAxis(state)

  switch (state.phase) {
    case 'straightGreen': {
      const walkBlocking = currentWalk?.active && currentWalk.activeUntil !== null && currentWalk.activeUntil > state.now
      if (walkBlocking) {
        return state
      }

      if (elapsed < TIMINGS.straightMinMs) {
        return state
      }

      const otherAxis = oppositeAxis(state.activeAxis)
      const currentDemand = summary.axisDemand[state.activeAxis]
      const otherDemand = summary.axisDemand[otherAxis]
      const priorityAxis = state.priorityAxis

      if (state.activeAxis === priorityAxis) {
        if (otherDemand > 0 && currentDemand === 0) {
          return beginPhase(state, 'straightYellow')
        }

        if (otherDemand > 0 && currentDemand > 0 && elapsed >= TIMINGS.straightMinMs + 5_000) {
          return beginPhase(state, 'straightYellow')
        }

        return state
      }

      if (otherDemand > 0 || currentDemand === 0) {
        return beginPhase(state, 'straightYellow')
      }

      return state
    }
    case 'straightYellow':
      return elapsed >= TIMINGS.yellowMs ? beginPhase(state, 'allRedToLeft') : state
    case 'allRedToLeft': {
      if (elapsed < TIMINGS.allRedMs) {
        return state
      }

      return beginPhase(state, 'leftGreen')
    }
    case 'leftGreen':
      return elapsed >= TIMINGS.leftMinMs ? beginPhase(state, 'leftYellow') : state
    case 'leftYellow':
      return elapsed >= TIMINGS.yellowMs ? beginPhase(state, 'allRedToSwap') : state
    case 'allRedToSwap': {
      if (elapsed < TIMINGS.allRedMs) {
        return state
      }

      return beginPhase({ ...state, activeAxis: oppositeAxis(state.activeAxis) }, 'straightGreen')
    }
  }
}

function maybeAdvancePhase(state: SimState, summary: TrafficSummary): SimState {
  let nextState = state
  let guard = 0

  while (guard < 6) {
    const advanced = tickPhase(nextState, summary)
    if (advanced === nextState) {
      break
    }

    nextState = advanced
    guard += 1
  }

  return nextState
}

function advanceCars(state: SimState, deltaMs: number, summary: TrafficSummary): Car[] {
  const nextCars: Car[] = []
  const movementSeconds = deltaMs / 1_000
  const walkBlocking = state.walks[axisToCrossing(state.activeAxis)].active

  for (const car of state.cars) {
    const signal = canCarMove(car, state, summary, walkBlocking)
    const nextProgress = signal
      ? Math.min(car.pathLength, car.progress + car.speed * movementSeconds * state.speed)
      : Math.min(car.progress, car.stopDistance)

    if (nextProgress < car.pathLength + 8) {
      nextCars.push({ ...car, progress: nextProgress })
    }
  }

  return nextCars
}

function spawnCars(state: SimState, now: number) {
  const nextCars = [...state.cars]
  const nextSpawnAt = { ...state.nextSpawnAt }

  for (const approach of APPROACHES) {
    for (const lane of LANE_ORDER) {
      const key = getLaneKey(approach, lane)
      while (now >= nextSpawnAt[key]) {
        const laneBlocked = nextCars.some((car) => car.approach === approach && car.lane === lane && car.progress < 60)
        if (laneBlocked) {
          nextSpawnAt[key] += 900
          break
        }

        const laneProfile = laneSpawnProfiles[lane]
        const intent: Intent = lane
        const path = buildCarPath(approach, lane, intent)
        const car: Car = {
          id: state.nextId + nextCars.length + 1,
          approach,
          lane,
          intent,
          path: path.points,
          pathLength: path.length,
          progress: 0,
          stopDistance: path.stopDistance,
          speed: laneProfile.speed,
          length: laneShape.carLength,
          width: laneShape.carWidth,
          color: LANE_COLORS[intent],
        }

        nextCars.push(car)
        nextSpawnAt[key] = now + randomBetween(laneProfile.minMs, laneProfile.maxMs)
      }
    }
  }

  return {
    cars: nextCars,
    nextSpawnAt,
  }
}

function updateWalks(state: SimState, now: number): Record<Crossing, WalkState> {
  const nextWalks: Record<Crossing, WalkState> = {
    NS: { ...state.walks.NS },
    EW: { ...state.walks.EW },
  }

  for (const crossing of ['NS', 'EW'] as Crossing[]) {
    const requiredAxis = crossing === 'NS' ? 'EW' : 'NS'
    const walk = nextWalks[crossing]

    if (walk.active && walk.activeUntil !== null && now >= walk.activeUntil) {
      nextWalks[crossing] = { requested: false, active: false, activeUntil: null }
      continue
    }

    if (walk.requested && !walk.active && state.phase === 'straightGreen' && state.activeAxis === requiredAxis) {
      nextWalks[crossing] = {
        requested: true,
        active: true,
        activeUntil: now + TIMINGS.walkMs,
      }
    }
  }

  return nextWalks
}

function activeWalkForAxis(state: SimState) {
  const crossing = axisToCrossing(state.activeAxis)
  return state.walks[crossing]
}

function beginPhase(state: SimState, phase: Phase): SimState {
  return {
    ...state,
    phase,
    phaseStartedAt: state.now,
  }
}

function canCarMove(car: Car, state: SimState, summary: TrafficSummary, walkBlocking: boolean) {
  const axis = axisForApproach(car.approach)
  const isCommitted = car.progress >= car.stopDistance - 4

  if (isCommitted) {
    return true
  }

  if (state.activeAxis !== axis) {
    return false
  }

  if (car.intent === 'left') {
    const permissiveLeft =
      state.phase === 'straightGreen' &&
      summary.axisDemand[oppositeAxis(axis)] === 0 &&
      !walkBlocking

    return state.phase === 'leftGreen' || permissiveLeft
  }

  if (car.intent === 'right') {
    return state.phase === 'straightGreen'
  }

  return state.phase === 'straightGreen'
}

function axisForApproach(approach: Approach): Axis {
  return approach === 'N' || approach === 'S' ? 'NS' : 'EW'
}

function axisToCrossing(axis: Axis): Crossing {
  return axis === 'NS' ? 'EW' : 'NS'
}

function oppositeAxis(axis: Axis): Axis {
  return axis === 'NS' ? 'EW' : 'NS'
}

function randomBetween(minMs: number, maxMs: number) {
  return Math.floor(minMs + Math.random() * (maxMs - minMs))
}

function createInitialState(): SimState {
  const now = 0
  const nextSpawnAt = Object.fromEntries(
    APPROACHES.flatMap((approach) =>
      LANE_ORDER.map((lane) => [getLaneKey(approach, lane), randomBetween(200, 1_400)] as const),
    ),
  ) as Record<LaneKey, number>

  return {
    now,
    phase: 'straightGreen',
    activeAxis: 'NS',
    phaseStartedAt: now,
    priorityAxis: 'NS',
    paused: false,
    speed: 1,
    cars: [],
    walks: {
      NS: { requested: false, active: false, activeUntil: null },
      EW: { requested: false, active: false, activeUntil: null },
    },
    nextSpawnAt,
    nextId: 0,
  }
}

function buildCarPath(approach: Approach, lane: LaneKind, intent: Intent) {
  const startPoint = approachStartPoint(approach, lane)
  const stopPoint = approachStopPoint(approach, lane)
  const farExit = approachExitPoint(approach, lane, intent)
  const turnPivot = approachTurnPivot(approach, intent)

  const points =
    intent === 'straight'
      ? [startPoint, stopPoint, farExit]
      : [startPoint, stopPoint, turnPivot, farExit]

  return {
    points,
    length: polylineLength(points),
    stopDistance: polylineLength([startPoint, stopPoint]),
  }
}

function approachStartPoint(approach: Approach, lane: LaneKind): Point {
  const laneIndex = LANE_ORDER.indexOf(lane)
  if (approach === 'N') {
    return { x: laneCenterX('N', laneIndex), y: -140 }
  }

  if (approach === 'S') {
    return { x: laneCenterX('S', laneIndex), y: VIEW.height + 140 }
  }

  if (approach === 'W') {
    return { x: -140, y: laneCenterY('W', laneIndex) }
  }

  return { x: VIEW.width + 140, y: laneCenterY('E', laneIndex) }
}

function approachStopPoint(approach: Approach, lane: LaneKind): Point {
  const laneIndex = LANE_ORDER.indexOf(lane)
  if (approach === 'N') {
    return { x: laneCenterX('N', laneIndex), y: VIEW.centerY - VIEW.intersectionHalf }
  }

  if (approach === 'S') {
    return { x: laneCenterX('S', laneIndex), y: VIEW.centerY + VIEW.intersectionHalf }
  }

  if (approach === 'W') {
    return { x: VIEW.centerX - VIEW.intersectionHalf, y: laneCenterY('W', laneIndex) }
  }

  return { x: VIEW.centerX + VIEW.intersectionHalf, y: laneCenterY('E', laneIndex) }
}

function approachTurnPivot(approach: Approach, intent: Intent): Point {
  const offset = laneShape.turnInset
  if (approach === 'N') {
    return intent === 'left'
      ? { x: VIEW.centerX + offset, y: VIEW.centerY - 24 }
      : { x: VIEW.centerX - offset, y: VIEW.centerY + 24 }
  }

  if (approach === 'S') {
    return intent === 'left'
      ? { x: VIEW.centerX - offset, y: VIEW.centerY + 24 }
      : { x: VIEW.centerX + offset, y: VIEW.centerY - 24 }
  }

  if (approach === 'W') {
    return intent === 'left'
      ? { x: VIEW.centerX - 24, y: VIEW.centerY - offset }
      : { x: VIEW.centerX + 24, y: VIEW.centerY + offset }
  }

  return intent === 'left'
    ? { x: VIEW.centerX + 24, y: VIEW.centerY + offset }
    : { x: VIEW.centerX - 24, y: VIEW.centerY - offset }
}

function approachExitPoint(approach: Approach, lane: LaneKind, intent: Intent): Point {
  const laneIndex = LANE_ORDER.indexOf(lane)
  if (approach === 'N') {
    if (intent === 'left') return { x: VIEW.width + 140, y: VIEW.centerY - 24 }
    if (intent === 'right') return { x: -140, y: VIEW.centerY + 24 }
    return { x: laneCenterX('N', laneIndex), y: VIEW.height + 140 }
  }

  if (approach === 'S') {
    if (intent === 'left') return { x: -140, y: VIEW.centerY + 24 }
    if (intent === 'right') return { x: VIEW.width + 140, y: VIEW.centerY - 24 }
    return { x: laneCenterX('S', laneIndex), y: -140 }
  }

  if (approach === 'W') {
    if (intent === 'left') return { x: VIEW.centerX - 24, y: -140 }
    if (intent === 'right') return { x: VIEW.centerX + 24, y: VIEW.height + 140 }
    return { x: VIEW.width + 140, y: laneCenterY('W', laneIndex) }
  }

  if (intent === 'left') return { x: VIEW.centerX + 24, y: VIEW.height + 140 }
  if (intent === 'right') return { x: VIEW.centerX - 24, y: -140 }
  return { x: -140, y: laneCenterY('E', laneIndex) }
}

function polylineLength(points: Point[]) {
  let total = 0
  for (let index = 0; index < points.length - 1; index += 1) {
    total += distance(points[index], points[index + 1])
  }
  return total
}

function pointAlongPath(points: Point[], progress: number) {
  let remaining = Math.max(0, progress)

  for (let index = 0; index < points.length - 1; index += 1) {
    const start = points[index]
    const end = points[index + 1]
    const segmentLength = distance(start, end)

    if (remaining <= segmentLength) {
      const ratio = segmentLength === 0 ? 0 : remaining / segmentLength
      const x = start.x + (end.x - start.x) * ratio
      const y = start.y + (end.y - start.y) * ratio
      return { x, y, angle: angleBetween(start, end) }
    }

    remaining -= segmentLength
  }

  const last = points[points.length - 1]
  const prev = points[points.length - 2]
  return { x: last.x, y: last.y, angle: angleBetween(prev, last) }
}

function distance(a: Point, b: Point) {
  return Math.hypot(b.x - a.x, b.y - a.y)
}

function angleBetween(a: Point, b: Point) {
  return (Math.atan2(b.y - a.y, b.x - a.x) * 180) / Math.PI
}

function laneCenterX(approach: 'N' | 'S', laneIndex: number) {
  return approach === 'N'
    ? VIEW.centerX - VIEW.roadBand / 2 + 28 + laneIndex * laneSpacing
    : VIEW.centerX + 28 + laneIndex * laneSpacing
}

function laneCenterY(approach: 'W' | 'E', laneIndex: number) {
  return approach === 'W'
    ? VIEW.centerY - VIEW.roadBand / 2 + 28 + laneIndex * laneSpacing
    : VIEW.centerY + 28 + laneIndex * laneSpacing
}

