const data = await page.evaluate(() => {
  const cars = Array.from(document.querySelectorAll('g.cars > g'));
  const positions = cars.map(c => {
    const t = c.getAttribute('transform') || '';
    const m = t.match(/translate\(([-\d.]+) ([-\d.]+)\) rotate\(([-\d.]+)\)/);
    return m ? { x: +m[1], y: +m[2], r: +m[3] } : null;
  }).filter(Boolean);

  // Group by approach (rotation)
  const buckets = { N: [], S: [], E: [], W: [] };
  for (const p of positions) {
    if (p.r === 90) buckets.N.push(p); // heading south
    else if (p.r === -90) buckets.S.push(p); // heading north
    else if (p.r === 0) buckets.W.push(p); // heading east
    else if (p.r === 180) buckets.E.push(p); // heading west
  }

  // Show cars near intersection (within 100px of center 600,420)
  const nearIntersection = {};
  for (const [app, list] of Object.entries(buckets)) {
    nearIntersection[app] = list
      .filter(p => Math.abs(p.x - 600) < 200 && Math.abs(p.y - 420) < 200)
      .map(p => ({ x: Math.round(p.x), y: Math.round(p.y) }));
  }
  return { counts: Object.fromEntries(Object.entries(buckets).map(([k,v])=>[k,v.length])), nearIntersection };
});
return data;

const data = await page.evaluate(() => {
  const cars = Array.from(document.querySelectorAll('g.cars > g'));
  const out = [];
  for (const c of cars) {
    const t = c.getAttribute('transform') || '';
    const m = t.match(/translate\(([-\d.]+) ([-\d.]+)\) rotate\(([-\d.]+)\)/);
    if (!m) continue;
    const x = +m[1], y = +m[2], r = +m[3];
    // N approach (heading south, rotate 90) lane positions: 584 (L), 552 (S1), 520 (S2), 488 (R)
    if (r === 90) {
      out.push({ x: Math.round(x), y: Math.round(y) });
    }
  }
  out.sort((a,b)=>a.y-b.y);
  return out.slice(0, 30);
});
return data;

// Sample N approach lane S1 (x=552) deepest car y over 2 seconds
const samples = [];
for (let i = 0; i < 5; i++) {
  const data = await page.evaluate(() => {
    const cars = Array.from(document.querySelectorAll('g.cars > g'));
    let maxY = -Infinity, count552 = 0;
    for (const c of cars) {
      const t = c.getAttribute('transform') || '';
      const m = t.match(/translate\(([-\d.]+) ([-\d.]+)\) rotate\((\d+)\)/);
      if (!m) continue;
      const x = +m[1], y = +m[2], r = +m[3];
      if (r === 90 && Math.abs(x - 552) < 2) {
        count552++;
        if (y > maxY) maxY = y;
      }
    }
    return { maxY, count552 };
  });
  samples.push(data);
  await page.waitForTimeout(500);
}
return samples;

