      const southY = VIEW.centerY + VIEW.intersectionHalf + 19
      markers.push({
        key: 'walk-NS-north',
        x: VIEW.centerX - crosswalkSpan + t * crosswalkSpan * 2,
        y: northY,
      })
      markers.push({
        key: 'walk-NS-south',
        x: VIEW.centerX + crosswalkSpan - t * crosswalkSpan * 2,
        y: southY,
      })
    } else {
      // East crosswalk: walk south -> north. West crosswalk: north -> south.
