        x: eastX,
        y: VIEW.centerY + crosswalkSpan - t * crosswalkSpan * 2,
      })
      markers.push({
        key: 'walk-EW-west',
        x: westX,
        y: VIEW.centerY - crosswalkSpan + t * crosswalkSpan * 2,
      })
    }
  }

