function oppositeApproach(approach: Approach): Approach {
  return ({ N: 'S', S: 'N', E: 'W', W: 'E' } as const)[approach]
}

// Time (seconds) a permissive-left turner needs to clear the conflict zone
// once it starts rolling from the stop line. Opposing straight traffic that
// would arrive sooner than this disqualifies the gap.
const LEFT_TURN_CLEAR_SECONDS = 2.5

// True when no opposing-approach straight car is close enough to collide with
// this left-turning car. Used to gate permissive-left turns on a flashing
// yellow signal.
function hasSafeLeftGap(car: Car, cars: Car[]): boolean {
  const opposing = oppositeApproach(car.approach)

  for (const other of cars) {
    if (other.approach !== opposing) continue
    if (other.intent !== 'straight') continue

    // Any opposing straight car already past its own stop line is inside the
    // intersection (or about to enter) and would T-bone the turning car.
    if (other.progress > other.stopDistance - 4) {
      return false
    }

    const distanceToStopLine = other.stopDistance - other.progress
    const timeToStopLineSec = distanceToStopLine / other.speed
    if (timeToStopLineSec < LEFT_TURN_CLEAR_SECONDS) {
      return false
    }
  }

  return true
}

