edits.text:
Seconds a permissive-left turner needs to clear the conflict zone (the
// middle of the intersection) once it starts rolling from the stop line.
// An opposing straight car that would reach that conflict point sooner than
// this disqualifies the gap.
const LEFT_TURN_CLEAR_SECONDS = 2.2

// True when no opposing-approach straight car is close enough to collide with
// this left-turning car. Only oncoming **straight** traffic matters — right
// turners use their own lane and other left turners share the protected/
// permissive logic, so neither interferes with a permissive left.
function hasSafeLeftGap(car: Car, cars: Car[]): boolean {
  const opposing = oppositeApproach(car.approach)

  // Find the front-most opposing straight car (smallest distance-to-stop-line).
  // Any car queued behind it is necessarily further away and can't arrive at
  // the conflict point sooner, so a single threat check on the leader is
  // sufficient.
  let leader: Car | undefined
  let leaderDistance = Number.POSITIVE_INFINITY
  for (const other of cars) {
    if (other.approach !== opposing) continue
    if (other.intent !== 'straight') continue
    const distanceToStopLine = other.stopDistance - other.progress
    // Already past stop line → inside the intersection and will T-bone us.
    if (distanceToStopLine < 4) {
      return false
    }
    if (distanceToStopLine < leaderDistance) {
      leaderDistance = distanceToStopLine
      leader = other
    }
  }

  if (!leader) return true

  // Opposing car must travel its remaining distance plus roughly half the
  // intersection to actually reach the conflict point with the turning car.
  const distanceToConflict = leaderDistance + INTERSECTION.intersectionHalf
  const timeToConflictSec = distanceToConflict / leader.speed
  return timeToConflictSec >= LEFT_TURN_CLEAR_SECONDS

